<x-admin-layout title="Paket"><h1>Paket</h1><p class="muted">Perubahan berlaku untuk pengajuan baru. Snapshot event dan transaksi lama dipertahankan.</p><div class="card table-wrap"><table><thead><tr><th>Paket</th><th>Harga sandbox</th><th>Batas</th><th>Status & pengaturan</th></tr></thead><tbody>@foreach($packages as $p)<tr><td>{{ $p->name }}</td><td>{{ $p->price===null?'Belum ditetapkan':'Rp'.number_format($p->price,0,',','.') }}</td><td>{{ $p->positions_limit }} posisi · {{ $p->applications_limit }} lamaran · {{ $p->days_limit }} hari</td><td>{{ $p->active?'Tersedia':'Nonaktif' }}<details><summary>Ubah Paket</summary><form method="post" action="{{ route('admin.package.save',$p) }}" data-confirm="Simpan perubahan paket untuk pengajuan baru?">@csrf<label>Harga (Rp, kosong jika belum ditetapkan)<input type="number" name="price" value="{{ $p->price }}" min="0"></label><label>Batas posisi<input type="number" name="positions_limit" value="{{ $p->positions_limit }}" min="1" required></label><label>Batas lamaran<input type="number" name="applications_limit" value="{{ $p->applications_limit }}" min="1" required></label><label>Batas hari<input type="number" name="days_limit" value="{{ $p->days_limit }}" min="1" required></label><label>Status<select name="active"><option value="1" @selected($p->active)>Tersedia</option><option value="0" @selected(!$p->active)>Nonaktif</option></select></label><label>Alasan perubahan<input name="reason" required maxlength="500"></label><button class="btn">Simpan Paket</button></form></details></td></tr>@endforeach</tbody></table></div></x-admin-layout>